let barcodeRules={version:1,main:{enabled:true,prefixes:['MC'],length:14,charset:'alnum'},cell:{enabled:true,prefixes:['CELL'],length:16,charset:'alnum'},sn:{enabled:true,prefixes:['SN'],length:14,charset:'alnum'},pack:{enabled:true,prefixes:['PK'],length:14,charset:'alnum'}};let barcodeError='',ruleDraft=null;
function validateRuleSet(r){if(!r||!Number.isInteger(r.version)||r.version<1)throw Error('条码规则版本无效');for(let k of Object.keys(codeNames)){let x=r[k];if(!x||typeof x.enabled!=='boolean'||!Array.isArray(x.prefixes)||!x.prefixes.every(p=>typeof p==='string'&&/^[A-Za-z0-9_-]+$/.test(p))||x.prefixes.length>20||!Number.isInteger(x.length)||x.length<1||x.length>128||x.prefixes.some(p=>p.length>x.length)||!['alnum','numeric','printable'].includes(x.charset))throw Error(codeNames[k]+'规则配置无效');if(x.charset==='alnum'&&x.prefixes.some(p=>!/^[A-Za-z0-9]+$/.test(p)))throw Error(codeNames[k]+'前缀包含所选字符类型不允许的符号');if(x.charset==='numeric'&&x.prefixes.some(p=>!/^[0-9]+$/.test(p)))throw Error(codeNames[k]+'选择纯数字时，前缀也必须为数字')}return r}
try{let r=JSON.parse(localStorage.getItem(BARCODEKEY)||'null');if(r)barcodeRules=validateRuleSet(r)}catch{}
function checkBarcode(kind,code,rules=barcodeRules){let r=rules[kind];if(!r)return {ok:false,error:'未配置该类型条码规则'};if(!r.enabled)return {ok:true};if(typeof code!=='string'||!code)return {ok:false,error:'条码不能为空'};let name=codeNames[kind];if(code.length!==r.length)return {ok:false,error:`${name}位数错误：要求 ${r.length} 位，实际 ${code.length} 位`};if(r.prefixes.length&&!r.prefixes.some(p=>code.startsWith(p)))return {ok:false,error:`${name}开头错误：必须以 ${r.prefixes.join(' 或 ')} 开头（区分大小写）`};let re=r.charset==='numeric'?/^[0-9]+$/:r.charset==='alnum'?/^[A-Za-z0-9]+$/:/^[\x21-\x7E]+$/;if(!re.test(code))return {ok:false,error:name+'字符类型错误：'+{numeric:'只允许数字',alnum:'只允许英文字母和数字',printable:'只允许无空格的可打印英文字符'}[r.charset]};return {ok:true}}
