navs[navs.length-1][1].splice(1,0,['barcodes','▥','条码规则']);names.barcodes='条码规则';const beforeRulesAllowed=allowedPage;allowedPage=function(p){if(p==='barcodes')return auth?.role==='admin';return beforeRulesAllowed(p)};
function charsetLabel(c){return {alnum:'英文字母 + 数字',numeric:'纯数字',printable:'英文可打印字符（无空格）'}[c]}
renderers.barcodes=function(){return heading('条码规则','分别定义主码、电芯码、SN 和包装码的格式，扫描先校验再执行',badge('规则版本 V'+barcodeRules.version))+`<div class="notice">总位数包含前缀。前缀区分大小写，可设置多个允许值；任一条件不匹配就拦截，不生成绑定或增加产量。</div>`+`<div class="gridhalf">${Object.entries(codeNames).map(([k,label])=>panel(label+` <span class="badge teal">${k.toUpperCase()}</span>`,`<div class="formgrid"><label class="field">允许的开头前缀（逗号分隔）<input id="rule-${k}-prefix" value="${escapeHtml(barcodeRules[k].prefixes.join(','))}" placeholder="例如 MC,PB；留空表示不限前缀"></label><label class="field">条码总位数（含前缀）<input id="rule-${k}-length" type="number" min="1" max="128" value="${barcodeRules[k].length}"></label><label class="field">允许字符<select id="rule-${k}-charset">${['alnum','numeric','printable'].map(c=>`<option value="${c}" ${barcodeRules[k].charset===c?'selected':''}>${charsetLabel(c)}</option>`).join('')}</select></label><label class="checkrow"><input id="rule-${k}-enabled" type="checkbox" ${barcodeRules[k].enabled?'checked':''}>启用强制格式校验</label></div><p class="hint">当前规则：${barcodeRules[k].enabled?'强制校验':'未启用'} · ${barcodeRules[k].length} 位 · ${charsetLabel(barcodeRules[k].charset)}</p>`)).join('')}</div>`+panel('发布规则',`<div class="actions">${button('检查并发布新版本',"reviewBarcodeRules()",'primary')}<span class="sub">发布后对新的扫描立即生效，已有绑定和测试记录保留。</span></div>`)+panel('条码校验测试',`<div class="filters"><select id="ruleTryKind">${Object.entries(codeNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><input id="ruleTryCode" placeholder="输入条码，仅校验不入库" onkeydown="if(event.key==='Enter')tryBarcodeRule()">${button('测试当前已发布规则',"tryBarcodeRule()")}</div><div id="ruleTryResult" class="sub">可先验证样码是否符合规则。</div>`)+panel('默认演示样码',table(['类型','样码','总位数'],[['主码','MC261015000128','14'],['电芯码','CELL261015000456','16'],['SN 码','SN261015000128','14'],['包装码','PK261015000032','14']]))};
function readRuleDraft(){let r={version:barcodeRules.version+1};for(let k of Object.keys(codeNames)){let raw=$('#rule-'+k+'-prefix').value.trim();r[k]={enabled:$('#rule-'+k+'-enabled').checked,prefixes:[...new Set(raw.split(/[,，\s]+/).filter(Boolean))],length:Number($('#rule-'+k+'-length').value),charset:$('#rule-'+k+'-charset').value}}return validateRuleSet(r)}
function reviewBarcodeRules(){if(!requireAdmin())return;try{ruleDraft=readRuleDraft();modal('发布条码规则 V'+ruleDraft.version,table(['条码','前缀','总位数','字符类型','校验'],Object.entries(codeNames).map(([k,label])=>[label,escapeHtml(ruleDraft[k].prefixes.join(' / ')||'不限'),ruleDraft[k].length,charsetLabel(ruleDraft[k].charset),badge(ruleDraft[k].enabled?'启用':'停用')]))+`<p class="hint">新规则立即用于后续扫描，当前等待绑定的扫码上下文将清空。原有记录不重写。</p>`,button('取消','closeModal()')+button('确认发布',"publishBarcodeRules()",'primary'))}catch(e){toast(e.message)}}
function publishBarcodeRules(){if(!requireAdmin()||!ruleDraft)return;try{validateRuleSet(ruleDraft);localStorage.setItem(BARCODEKEY,JSON.stringify(ruleDraft));barcodeRules=ruleDraft;ruleDraft=null;wfCode='';autoPending=false;barcodeError='';adminLog('发布条码规则','V'+barcodeRules.version);closeModal();render();toast('规则已发布，新扫描立即校验')}catch(e){toast('发布失败：'+e.message)}}
function tryBarcodeRule(){let r=checkBarcode($('#ruleTryKind').value,$('#ruleTryCode').value.trim());$('#ruleTryResult').textContent=r.ok?'✓ 格式校验通过（未保存生产记录）':'✕ '+r.error;$('#ruleTryResult').style.color=r.ok?'#128765':'#c44350'}
const beforeRulesWork=wfWork;wfWork=function(){return (barcodeError?`<div class="statusbox fail" role="alert"><h2>条码被拦截</h2><p>${escapeHtml(barcodeError)}</p><p class="sub">未保存绑定、未增加产量；请重新扫描正确条码。</p></div>`:'')+beforeRulesWork()};
const beforeRulesAuto=wfAutoScan;wfAutoScan=function(){let code=$('#wfScan').value.trim();if(!code)return;let kind=autoStage===wfStage&&autoPending?{1:'cell',3:'sn',4:'pack'}[wfStage]:wfStage===4?'sn':'main';if(!enforceBarcode(kind,code))return;beforeRulesAuto()};
const beforeRulesLookup=wfLookup;wfLookup=function(){let c=$('#wfScan').value.trim();if(!c)return beforeRulesLookup();if(!enforceBarcode(wfStage===4?'sn':'main',c))return;beforeRulesLookup()};
const beforeRulesBind=wfBind;wfBind=function(kind,code){let c=code||'';if(!enforceBarcode(kind,c||''))return;beforeRulesBind(kind,code)};
const beforeRulesTest=wfTest;wfTest=function(result){let u=activeUnit();if(!u||!enforceBarcode('main',u.main))return;beforeRulesTest(result)};
const beforeRulesReset=wfResetScan;wfResetScan=function(){barcodeError='';beforeRulesReset()};const beforeRulesSwitch=wfSwitchStation;wfSwitchStation=function(){barcodeError='';beforeRulesSwitch()};
const beforeRulesBackup=backupData;backupData=function(){let d=beforeRulesBackup();d.barcodeRules=JSON.parse(JSON.stringify(barcodeRules));return d};const beforeRulesShape=validateBackupShape;validateBackupShape=function(b){let d=beforeRulesShape(b);if(d.barcodeRules)validateRuleSet(d.barcodeRules);return d};
// Apply the restored rule set only after the data restore succeeds.
const beforeRulesRestore=applyRestore;applyRestore=function(){let next=pendingRestore?.data.barcodeRules;let authorized=auth?.role==='admin'&&pendingRestore&&$('#restoreConfirm').checked;if(authorized&&next){try{validateRuleSet(next);localStorage.setItem(BARCODEKEY,JSON.stringify(next))}catch(e){toast('条码规则无法恢复：'+e.message);return}}let previous=barcodeRules;beforeRulesRestore();if(authorized&&pendingRestore===null){if(next)barcodeRules=next;barcodeError='';render()}else if(authorized&&next){localStorage.setItem(BARCODEKEY,JSON.stringify(previous))}};
window.addEventListener('storage',e=>{if(e.key===BARCODEKEY&&e.newValue){try{let r=validateRuleSet(JSON.parse(e.newValue));barcodeRules=r;autoPending=false;wfCode='';barcodeError='';render()}catch{}}});
